  def getUpdates(bridge_id: art.Art.BridgeId, observationKind: ObservationKind.Type, container: art.DataContent): Map[String, String] = {
    observationKind match {
      case eit_image_availability_coordinator.runtimemonitor.ObservationKind.EITImageAvailabilitySystem_Instance_coordination_image_event_qualification_postInit =>
        var updates: Map[String, String] = Map.empty
        val postContainer = container.asInstanceOf[eit_image_availability_coordinator.EIT_Image_Availability_Coordinator.ImageEventQualification_coordination_image_event_qualification_PostState_Container_PS]
